// spec: specs/premium-store.md (раздел 3.3)
// seed: tests/seed.free.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/free-r13.json'), colorScheme: 'dark' });

test.describe('Раунд 13: «בוסטים» и «סופר לייק» (#4ef651)', () => {
  test('⚡ → /boosts, ⭐ → /super-likes, суперлайк не уходит @iphone @prod-safe', async ({ page }) => {
    const swipeRequests: string[] = [];
    page.on('request', (r) => {
      if (r.method() !== 'GET' && /swipe|superlike|super_like|boost/i.test(r.url())) swipeRequests.push(`${r.method()} ${r.url()}`);
    });

    // 1. Проверить предусловие на `/boosts` и `/super-likes` (0 и 0), вернуться на `/discover`, дождаться карточки.
    await page.goto('/boosts');
    const boostsHave = page.getByText(/^\d+ בוסטים$/);
    await expect(boostsHave).toBeVisible();
    const boostsText = (await boostsHave.textContent()) ?? '';
    test.skip(!/^0 בוסטים$/.test(boostsText.trim()), `предусловие: 0 бустов, сейчас «${boostsText}» — ⚡ активирует буст`);

    await page.goto('/super-likes');
    const slHave = page.getByText(/^\d+ סופר לייק$/);
    await expect(slHave).toBeVisible();
    const slText = (await slHave.textContent()) ?? '';
    test.skip(!/^0 סופר לייק$/.test(slText.trim()), `предусловие: 0 суперлайков, сейчас «${slText}» — ⭐ отправит суперлайк`);

    await page.goto('/discover');
    const star = page.getByRole('button', { name: 'סופר לייק' });
    await expect(star).toBeVisible();

    // 2. ⚡ в шапке → смотреть URL; «назад».
    await page.getByTestId('header-boost').click();
    await expect(page).toHaveURL(/\/boosts/);
    await expect(page.getByText('בוסטים', { exact: true }).first()).toBeVisible();
    await expect(page.getByText('חנות', { exact: true })).toHaveCount(0);
    await expect(page.getByText('0 בוסטים', { exact: true })).toBeVisible();
    await page.getByRole('button', { name: 'חזרה' }).click();
    await expect(page).toHaveURL(/\/discover/);

    // 3. ⭐ на карточке → смотреть URL; «назад».
    await expect(star).toBeVisible();
    await star.click();
    await expect(page).toHaveURL(/\/super-likes/);
    await expect(page.getByText('סופר לייק', { exact: true }).first()).toBeVisible();
    await page.getByRole('button', { name: 'חזרה' }).click();
    await expect(page).toHaveURL(/\/discover/);

    expect(swipeRequests, 'swipe/superlike/boost не отправлялись').toEqual([]);
  });
});
